1	/**
2	 * Decode a Base64URL‐encoded payload into raw bytes.
3	 *
4	 * Base64URL is a URL‐safe variant of Base64:
5	 *  - '-' replaces '+'
6	 *  - '_' replaces '/'
7	 *  - padding ('=') may be omitted
8	 *
9	 * @param input - Base64URL data as a string or any BufferSource.
10	 * @returns An ArrayBuffer containing the decoded bytes.
11	 * @throws TypeError if `input` is neither string nor BufferSource.
12	 */
13	export function decodeBase64url(input: string | BufferSource): ArrayBuffer {
14	    // 1) Turn BufferSource into string
15	    let b64url: string;
16	    if (typeof input === 'string') {
17	        b64url = input;
18	    } else if (ArrayBuffer.isView(input) || input instanceof ArrayBuffer) {
19	        b64url = new TextDecoder().decode(input as ArrayBuffer);
20	    } else {
21	        throw new TypeError(`Expected string or BufferSource, but got ${typeof input}`);
22	    }
23	
24	    // 2) Normalize to standard Base64
25	    //    - swap URL chars back
26	    //    - pad with '=' to a multiple of 4
27	    const b64 = b64url
28	        .replace(/-/g, '+')
29	        .replace(/_/g, '/')
30	        .padEnd(Math.ceil(b64url.length / 4) * 4, '=');
31	
32	    // 3) Decode to binary string
33	    const binary = window.atob(b64);
34	
35	    // 4) Build ArrayBuffer from char codes
36	    const len = binary.length;
37	    const bytes = new Uint8Array(len);
38	    for (let i = 0; i < len; i++) {
39	        bytes[i] = binary.charCodeAt(i);
40	    }
41	
42	    return bytes.buffer;
43	}
