3	describe('decodeBase64url', () => {
4	    const textDecoder = new TextDecoder();
5	
6	    it('decodes standard base64url without padding', () => {
7	        const input = 'SGVsbG8td29ybGQ'; // "Hello-world"
8	        const output = decodeBase64url(input);
9	        expect(textDecoder.decode(output)).toBe('Hello-world');
10	    });
11	
12	    it('decodes base64url with missing padding', () => {
13	        const input = 'Zm9vYmFy'; // "foobar"
14	        const output = decodeBase64url(input);
15	        expect(textDecoder.decode(output)).toBe('foobar');
16	    });
17	
18	    it('decodes padded base64url strings', () => {
19	        expect(textDecoder.decode(decodeBase64url('TQ=='))).toBe('M');
20	        expect(textDecoder.decode(decodeBase64url('TWE='))).toBe('Ma');
21	    });
22	
23	    it('decodes URL-safe characters', () => {
24	        const input = 'YWJjMTIzLV8'; // "abc123-_"
25	        const output = decodeBase64url(input);
26	        expect(textDecoder.decode(output)).toBe('abc123-_');
27	    });
28	
29	    it('decodes ArrayBuffer input', () => {
30	        const encoder = new TextEncoder();
31	        const arr = encoder.encode('U29tZS1kYXRh'); // "Some-data"
32	        const output = decodeBase64url(arr);
33	        expect(textDecoder.decode(output)).toBe('Some-data');
34	    });
35	
36	    it('decodes Uint8Array view input', () => {
37	        const encoder = new TextEncoder();
38	        const uint8 = encoder.encode('U29tZS1kYXRh'); // "Some-data"
39	        const view = new Uint8Array(uint8.buffer);
40	        const output = decodeBase64url(view);
41	        expect(textDecoder.decode(output)).toBe('Some-data');
42	    });
43	
44	    it('returns correct ArrayBuffer length', () => {
45	        const input = 'U3BlY2lhbC1sZW5ndGg='; // "Special-length"
46	        const output = decodeBase64url(input);
47	        expect(output.byteLength).toBe('Special-length'.length);
48	    });
49	
50	    it('handles empty string input', () => {
51	        const output = decodeBase64url('');
52	        expect(output.byteLength).toBe(0);
53	    });
54	
55	    it('decodes minimal input without padding', () => {
56	        // "M" => "TQ"
57	        const output = decodeBase64url('TQ');
58	        expect(textDecoder.decode(output)).toBe('M');
59	    });
60	
61	    it('throws on non-string, non-BufferSource inputs', () => {
62	        // @ts-ignore
63	        expect(() => decodeBase64url(123)).toThrow(TypeError);
64	        // @ts-ignore
65	        expect(() => decodeBase64url({})).toThrow(TypeError);
66	        // @ts-ignore
67	        expect(() => decodeBase64url(null)).toThrow(TypeError);
68	    });
69	
70	    it('throws on invalid base64url strings', () => {
71	        const invalidInputs = ['!!!!', 'abcd*efg'];
72	        invalidInputs.forEach((input) => {
73	            expect(() => decodeBase64url(input)).toThrow();
74	        });
75	    });
76	
77	    it('decodes DataView input', () => {
78	        const encoder = new TextEncoder();
79	        const bytes = encoder.encode('U2FtcGxlLWRhdGE'); // "Sample-data"
80	        const dataView = new DataView(bytes.buffer);
81	        const output = decodeBase64url(dataView);
82	        expect(new TextDecoder().decode(output)).toBe('Sample-data');
83	    });
84	
85	    it('throws on inputs with length mod 4 == 1', () => {
86	        // Base64URL lengths of 1 are invalid
87	        expect(() => decodeBase64url('A')).toThrow();
88	        expect(() => decodeBase64url('ABCD1')).toThrow();
89	    });
90	
91	    it('throws on improper padding positions', () => {
92	        const invalid = ['SG=V', 'SGVsbG8=V29ybGQ='];
93	        invalid.forEach((input) => {
94	            expect(() => decodeBase64url(input)).toThrow();
95	        });
96	    });
97	});
