5	@Injectable({ providedIn: 'root' })
6	export class WebauthnService {
7	    private webauthnApiService = inject(WebauthnApiService);
8	
9	    async getCredential(): Promise<PublicKeyCredential | undefined> {
10	        const publicKeyCredentialOptions = await this.webauthnApiService.getAuthenticationOptions();
11	
12	        const assertionOptions: PublicKeyCredentialRequestOptions = {
13	            challenge: decodeBase64url(publicKeyCredentialOptions.challenge),
14	            timeout: publicKeyCredentialOptions.timeout,
15	            rpId: publicKeyCredentialOptions.rpId,
16	            allowCredentials: publicKeyCredentialOptions.allowCredentials
17	                ? publicKeyCredentialOptions.allowCredentials.map((credential) => {
18	                      return {
19	                          type: credential.type,
20	                          id: decodeBase64url(credential.id),
21	                          transports: credential.transports,
22	                      };
23	                  })
24	                : undefined,
25	            userVerification: publicKeyCredentialOptions.userVerification,
26	            extensions: publicKeyCredentialOptions.extensions,
27	        };
28	
29	        const credentialRequestOptions: CredentialRequestOptions = {
30	            publicKey: assertionOptions,
31	        };
32	
33	        const credential = (await navigator.credentials.get(credentialRequestOptions)) ?? undefined;
34	        return credential as PublicKeyCredential | undefined;
35	    }
36	}
